/* Shared demo planner. Templates only are persisted locally; no server or real accounts. */
(function(){
'use strict';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parse=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))throw Error('date');let d=new Date(s+'T12:00:00');if(!Number.isFinite(+d)||iso(d)!==s)throw Error('date');return d};
function plannedDates(d,today){
 let dates=[];
 if(d.mode==='dates')dates=[...new Set(d.dates)].sort();
 else{let a=parse(d.from),b=parse(d.mode==='single'?d.from:d.to);if(b<a)throw Error('range');if((b-a)/86400000>366)throw Error('long');for(let x=new Date(a);x<=b;x.setDate(x.getDate()+1)){if(d.mode!=='weekly'||d.days.includes(x.getDay()))dates.push(iso(x))}}
 dates=dates.filter(s=>{parse(s);return s>=today});
 if(!dates.length)throw Error('empty');return dates;
}
function checkedSlots(input){
 if(!input.length)throw Error('slots');let slots=input.map(s=>({...s})).sort((a,b)=>a.start.localeCompare(b.start));
 for(let i=0;i<slots.length;i++){let s=slots[i];if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.end)||s.start>=s.end)throw Error('time');if(i&&s.start<slots[i-1].end)throw Error('overlap')}return slots;
}
function expand(d,today){
 const dates=plannedDates(d,today);
 if(!d.slots.length)throw Error('slots');
 if(!d.branches.length)throw Error('branches');
 if(d.count<1||d.count>100||!Number.isInteger(d.count))throw Error('count');
 if(!(d.rate>0&&d.rate<=500))throw Error('rate');
 let result=[];for(const date of dates)for(const city of [...new Set(d.branches)])for(const s of checkedSlots(d.individualTimes?(d.dateSlots?.[date]||d.slots):d.slots))result.push({date,city,...s,count:d.count,rate:d.rate,roleKey:d.roleKey,otherSector:d.otherSector?.trim()||'',scope:d.scope,sameTeam:d.sameTeam});
 if(result.length>1500)throw Error('large');return result;
}
let cfg,draft,root,oldFocus;
const t=(f,e)=>cfg.lang==='en'?e:f;
const q=s=>root.querySelector(s);
function key(){return 'dispo-post-templates-v1:'+cfg.key}
function templates(){try{let a=JSON.parse(localStorage.getItem(key())||'[]');return Array.isArray(a)?a.filter(x=>x&&typeof x.name==='string'&&x.draft&&Array.isArray(x.draft.slots)&&Array.isArray(x.draft.branches)).slice(0,30):[]}catch{return []}}
function msg(code){return ({other:t('Précisez le secteur (obligatoire).','Specify the sector (required).'),date:t('Choisissez une date valide.','Choose a valid date.'),range:t('La fin de la période doit suivre le début.','The range must end on or after its start.'),long:t('Limitez la période à un an.','Limit the range to one year.'),empty:t('Sélectionnez au moins une date à venir et un jour de semaine applicable.','Choose at least one upcoming date and an applicable weekday.'),slots:t('Ajoutez au moins un créneau.','Add at least one time slot.'),time:t('Chaque fin doit suivre son début, le même jour.','Every end time must follow its start on the same day.'),overlap:t('Les créneaux se chevauchent. Ajustez les heures; utilisez le nombre de personnes pour un même quart.','Time slots overlap. Adjust the hours; use headcount for the same shift.'),branches:t('Cochez au moins une succursale.','Select at least one location.'),count:t('Choisissez entre 1 et 100 personnes par quart.','Choose 1–100 people per shift.'),rate:t('Indiquez un taux entre 1 et 500 $/h.','Enter a rate between $1 and $500/h.'),large:t('Plus de 1 500 créneaux : réduisez la période ou les succursales.','More than 1,500 slots: reduce the range or locations.')})[code]||t('Vérifiez les champs.','Check the fields.')}
function collect(){if(!root)return;if(cfg.employee&&q('#ds-name'))draft.templateName=q('#ds-name').value;for(const n of ['otherSector','roleKey','from','to','mode','scope'])if(q('[name='+n+']'))draft[n]=q('[name='+n+']').value;draft.rate=Number(q('[name=rate]').value);draft.count=cfg.employee?1:Number(q('[name=count]').value);draft.days=[...root.querySelectorAll('[name=weekday]:checked')].map(e=>+e.value);draft.branches=cfg.employee?[cfg.branches[0]]:[...root.querySelectorAll('[name=branch]:checked')].map(e=>e.value);draft.sameTeam=!!q('[name=sameTeam]')?.checked;if(cfg.employee){draft.individualTimes=!!q('[name=individualTimes]')?.checked;draft.dateSlots=draft.dateSlots||{};for(const el of root.querySelectorAll('[data-times-date]'))draft.dateSlots[el.dataset.timesDate]=[...el.querySelectorAll('.ds-date-time')].map(row=>({start:row.querySelector('[name=dateStart]').value,end:row.querySelector('[name=dateEnd]').value}))}draft.slots=[...root.querySelectorAll('.ds-slot')].map(el=>({start:el.querySelector('[name=start]').value,end:el.querySelector('[name=end]').value}));}
function preview(ignoreQuota=false){collect();try{if(cfg.roles.find(r=>String(r.key)===draft.roleKey)?.other&&!draft.otherSector?.trim())throw Error('other');let rows=expand(draft,iso(new Date())),dates=new Set(rows.map(x=>x.date));const quota=ignoreQuota?null:cfg.validate?.(rows);if(quota){q('#ds-preview').textContent=quota;q('#ds-publish').disabled=true;return null}if(cfg.employee){q('#ds-preview').innerHTML=`<strong>${dates.size} ${t('jour(s) choisi(s)','selected day(s)')}</strong><p>${draft.individualTimes?t('Heures personnalisées par date','Custom hours for each date'):draft.slots.map(s=>s.start+'–'+s.end).join(' · ')}</p><details><summary>${t('Vérifier mes dates','Review my dates')}</summary><div class="ds-summary">${rows.map(r=>escape(friendlyDate(r.date))+' · '+r.start+'–'+r.end).join('<br>')}</div></details>`;q('#ds-publish').disabled=false;q('#ds-error').textContent='';return rows}q('#ds-preview').innerHTML=`<strong>${rows.length} ${t(cfg.employee?'disponibilités':'quarts',cfg.employee?'availability slots':'shifts')}</strong><p>${dates.size} ${t('dates','dates')} × ${draft.slots.length} ${t('créneaux par jour','slots per day')}${cfg.employee?'':` × ${draft.branches.length} ${t('succursales','locations')} · ${rows.length*draft.count} ${t('places au total','total openings')}`}</p><details><summary>${t('Voir les dates et heures avant publication','Review dates and times before publishing')}</summary><div class="ds-summary">${rows.map(r=>`${escape(r.date)} · ${escape(r.city)} · ${r.start}–${r.end}`).join('<br>')}</div></details>`;q('#ds-publish').disabled=false;q('#ds-error').textContent='';return rows}catch(e){q('#ds-preview').innerHTML=`<p>${msg(e.message)}</p>`;q('#ds-publish').disabled=true;return null}}
function friendlyDate(s){return parse(s).toLocaleDateString(cfg.lang==='en'?'en-CA':'fr-CA',{weekday:'short',day:'numeric',month:'short'})}
function dateHours(){let dates;try{dates=plannedDates(draft,iso(new Date()))}catch{return `<p>${t('Choisis une date pour ajouter tes heures.','Choose a date to add your hours.')}</p>`}return dates.map(date=>{const slots=draft.dateSlots?.[date]||draft.slots;return `<div class="ds-day-hours" data-times-date="${date}"><h4>${escape(friendlyDate(date))}</h4>${slots.map((slot,i)=>`<div class="ds-date-time"><label>${t('De','From')}<input type="time" name="dateStart" value="${slot.start}" aria-label="${t('Début','Start')} ${date} ${i+1}"></label><label>${t('À','To')}<input type="time" name="dateEnd" value="${slot.end}" aria-label="${t('Fin','End')} ${date} ${i+1}"></label>${slots.length>1?`<button type="button" class="ds-secondary" data-do="removeDateSlot" data-date="${date}" data-index="${i}">${t('Retirer','Remove')}</button>`:''}</div>`).join('')}<button type="button" class="ds-secondary" data-do="addDateSlot" data-date="${date}">+ ${t('Ajouter une plage horaire','Add a time slot')}</button></div>`}).join('')}
function drawEmployee(){
 if(draft.mode==='single'){draft.mode='dates';draft.dates=[draft.from]}
 const today=iso(new Date()),tomorrowDate=new Date();tomorrowDate.setDate(tomorrowDate.getDate()+1);const tomorrow=iso(tomorrowDate);
 root.innerHTML=`<section class="ds-dialog ds-simple" role="dialog" aria-modal="true" aria-labelledby="ds-title"><div class="ds-head"><h2 id="ds-title">${t('Offrir mes disponibilités','Offer my availability')}</h2><button class="ds-secondary" data-do="close" aria-label="${t('Fermer','Close')}">×</button></div>
 <section class="ds-section"><h3>1. ${t('Quels jours?','Which days?')}</h3><div class="ds-options">${[[today,t('Aujourd’hui','Today')],[tomorrow,t('Demain','Tomorrow')]].map(([date,label])=>`<button type="button" class="ds-secondary ds-date-chip" data-do="quickdate" data-date="${date}" aria-pressed="${draft.mode==='dates'&&draft.dates.includes(date)}">${label}</button>`).join('')}<button type="button" class="ds-secondary ds-date-chip" data-do="otherdate" aria-expanded="false" aria-controls="ds-other-date">${t('Autre date','Other date')}</button></div>
 <div class="ds-date-add" id="ds-other-date" hidden><label>${t('Choisir une date','Choose a date')}<input type="date" id="ds-date" min="${today}" value="${draft.from}"></label><button type="button" class="ds-secondary" data-do="adddate">+ ${t('Ajouter','Add')}</button></div>
 ${draft.mode==='dates'?`<div class="ds-options ds-chosen">${draft.dates.map((d,i)=>`<button type="button" class="ds-secondary" data-do="removedate" data-index="${i}" aria-label="${t('Retirer','Remove')} ${escape(friendlyDate(d))}">${escape(friendlyDate(d))} ×</button>`).join('')}</div>`:''}
 <details class="ds-repeat" ${draft.mode!=='dates'?'open':''}><summary>${t('Répéter sur plusieurs semaines (facultatif)','Repeat over several weeks (optional)')}</summary><label>${t('Répéter','Repeat')}<select name="mode">${[['dates',t('Non : utiliser les dates ci-dessus','No: use the dates above')],['weekly',t('Certains jours chaque semaine','Selected weekdays')],['daily',t('Tous les jours','Every day')]].map(([v,l])=>`<option value="${v}" ${draft.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="ds-grid" ${draft.mode==='dates'?'hidden':''}><label>${t('Du','From')}<input type="date" name="from" min="${today}" value="${draft.from}"></label><label>${t('Au','Until')}<input type="date" name="to" min="${today}" value="${draft.to}"></label></div><div class="ds-options" ${draft.mode==='weekly'?'':'hidden'}>${[1,2,3,4,5,6,0].map((n,i)=>`<label class="ds-check"><input type="checkbox" name="weekday" value="${n}" ${draft.days.includes(n)?'checked':''}>${t(['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][i],['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i])}</label>`).join('')}</div></details></section>
 <section class="ds-section"><h3>2. ${t('De quelle heure à quelle heure?','What time?')}</h3><label class="ds-check ds-custom-hours"><input type="checkbox" name="individualTimes" ${draft.individualTimes?'checked':''}>${t('Des heures différentes selon la date','Different hours for each date')}</label><div ${draft.individualTimes?'hidden':''}>${draft.slots.map((s,i)=>`<div class="ds-slot"><label>${t('De','From')}<input type="time" name="start" value="${s.start}"></label><label>${t('À','To')}<input type="time" name="end" value="${s.end}"></label>${draft.slots.length>1?`<button type="button" class="ds-secondary" data-do="removeslot" data-index="${i}">${t('Retirer','Remove')}</button>`:''}</div>`).join('')}<p>${t('Ces heures s’appliquent à toutes les dates choisies.','These hours apply to every selected date.')}</p><button type="button" class="ds-secondary" data-do="addslot">+ ${t('Ajouter une plage horaire','Add another time slot')}</button></div>${draft.individualTimes?dateHours():''}</section>
 <section class="ds-section"><h3>3. ${t('Quel travail?','What work?')}</h3><div class="ds-grid"><label>${t('Type de travail','Type of work')}<select name="roleKey">${cfg.roles.map(r=>`<option value="${escape(r.key)}" ${draft.roleKey===String(r.key)?'selected':''}>${escape(r.label)}</option>`).join('')}</select></label><label>${t('Taux souhaité ($ CA/h brut)','Desired rate (CAD/h gross)')}<input type="number" name="rate" min="1" max="500" step="0.25" value="${draft.rate}"></label></div>${cfg.roles.find(r=>String(r.key)===draft.roleKey)?.other?`<label>${t('Précisez le secteur (obligatoire)','Specify the sector (required)')}<input name="otherSector" required maxlength="80" value="${escape(draft.otherSector||'')}"></label>`:''}</section>
 <div id="ds-preview" class="ds-preview" aria-live="polite"></div><p>${t('Tu restes libre d’accepter ou de refuser une offre.','You remain free to accept or decline an offer.')}</p><div id="ds-error" class="ds-error" role="status"></div><div class="ds-actions"><button type="button" class="ds-secondary" data-do="close">${t('Annuler','Cancel')}</button><button type="button" id="ds-publish" data-do="publish">${t('Offrir mes disponibilités','Offer my availability')}</button></div><p class="ds-simulation">${t('Démo : publication simulée.','Demo: simulated posting.')}</p>
 <section class="ds-templates"><h3>${t('Mes disponibilités enregistrées','My saved availability')}</h3>${templates().length?`<div class="ds-flex"><select id="ds-template" aria-label="${t('Disponibilité enregistrée','Saved availability')}"><option value="">${t('Choisir…','Choose…')}</option>${templates().map(x=>`<option value="${x.id}">${escape(x.name)}</option>`).join('')}</select><button type="button" class="ds-secondary" data-do="load">${t('Réutiliser','Reuse')}</button><button type="button" class="ds-secondary" data-do="delete">${t('Supprimer','Delete')}</button></div>`:`<p>${t('Aucune disponibilité enregistrée pour le moment.','No saved availability yet.')}</p>`}<details><summary>${t('Enregistrer ces disponibilités pour plus tard','Save this availability for later')}</summary><label>${t('Nom','Name')}<input id="ds-name" maxlength="60" value="${escape(draft.templateName||'')}" placeholder="${t('Ex. Mes après-midis libres','E.g. My free afternoons')}"></label><button type="button" class="ds-secondary" data-do="save">${t('Enregistrer','Save')}</button><p>${t('Conservé sur cet appareil. Cela ne publie rien. Vérifie les dates avant de réutiliser.','Saved on this device, without posting. Check dates before reusing.')}</p></details><p id="ds-save-status" role="status"></p></section></section>`;
 preview();
}

function draw(){if(cfg.employee)return drawEmployee();root.innerHTML=`<section class="ds-dialog" role="dialog" aria-modal="true" aria-labelledby="ds-title"><div class="ds-head"><div><h2 id="ds-title">${t(cfg.employee?'Planifier mes disponibilités':'Planifier des quarts',cfg.employee?'Plan my availability':'Plan shifts')}</h2><p>${t('Une date, plusieurs jours ou un mois complet.','One date, several days or an entire month.')}</p></div><button type="button" class="ds-secondary" data-do="close" aria-label="${t('Fermer','Close')}">×</button></div><div class="ds-templates"><h3>${t('Mes modèles enregistrés','My saved templates')}</h3><div class="ds-flex"><select id="ds-template" aria-label="${t('Modèle enregistré','Saved template')}" style="flex:1"><option value="">${t('Choisir un modèle…','Choose a template…')}</option>${templates().map(x=>`<option value="${x.id}">${escape(x.name)}</option>`).join('')}</select><button type="button" class="ds-secondary" data-do="load">${t('Charger','Load')}</button><button type="button" class="ds-secondary" data-do="delete">${t('Supprimer','Delete')}</button></div><p>${t('Modèles conservés dans ce navigateur uniquement, séparés par enseigne et par rôle. Aucun compte réel.','Templates stay in this browser only, separated by brand and role. No real account.')}</p></div><div class="ds-grid ds-section"><label>${t(cfg.employee?'Ce que je peux faire':'Poste',cfg.employee?'What I can do':'Role')}<select name="roleKey">${cfg.roles.map(r=>`<option value="${escape(r.key)}" ${draft.roleKey===String(r.key)?'selected':''}>${escape(r.label)}</option>`).join('')}</select></label>${cfg.roles.find(r=>String(r.key)===draft.roleKey)?.other?`<label>${t('Précisez le secteur (obligatoire)','Specify the sector (required)')}<input name="otherSector" required maxlength="80" value="${escape(draft.otherSector||'')}" placeholder="${t('Ex. Agriculture','E.g. Agriculture')}"></label>`:''}<label>${t('Taux brut · $ CA / h','Gross rate · CAD / h')}<input type="number" name="rate" min="1" max="500" step="0.25" value="${draft.rate}"></label></div>${cfg.employee?'':`<div class="ds-section"><div class="ds-flex"><h3>${t('Succursales concernées','Locations included')}</h3><button class="ds-secondary" type="button" data-do="allbranches">${t('Toutes les succursales','All locations')}</button></div><div class="ds-options">${cfg.branches.map(c=>`<label class="ds-check"><input type="checkbox" name="branch" value="${escape(c)}" ${draft.branches.includes(c)?'checked':''}>${escape(c)}</label>`).join('')}</div><p>${t('Les mêmes dates et heures seront créées pour chaque succursale cochée.','The same dates and times will be created for every selected location.')}</p></div>`}<div class="ds-section"><h3>${t('Quand ?','When?')}</h3><div class="ds-grid"><label>${t('Répétition','Repeat')}<select name="mode">${[['single',t('Une seule date','One date')],['dates',t('Plusieurs dates au choix','Choose several dates')],['daily',t('Tous les jours de la période','Every day in the range')],['weekly',t('Chaque semaine, jours choisis','Weekly, on selected days')]].map(([k,l])=>`<option value="${k}" ${draft.mode===k?'selected':''}>${l}</option>`).join('')}</select></label><label>${t('Raccourci : mois complet','Shortcut: entire month')}<div class="ds-flex"><input type="month" id="ds-month" value="${draft.from.slice(0,7)}" style="flex:1"><button type="button" class="ds-secondary" data-do="month">${t('Appliquer','Apply')}</button></div></label></div><div class="ds-grid" style="margin-top:14px" ${draft.mode==='dates'?'hidden':''}><label>${t('Du / le','From / on')}<input type="date" name="from" value="${draft.from}"></label><label ${draft.mode==='single'?'hidden':''}>${t('Au (inclus)','Through (inclusive)')}<input type="date" name="to" value="${draft.to}"></label></div><div ${draft.mode==='weekly'?'':'hidden'} class="ds-options">${[1,2,3,4,5,6,0].map((n,i)=>`<label class="ds-check"><input type="checkbox" name="weekday" value="${n}" ${draft.days.includes(n)?'checked':''}>${t(['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][i],['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i])}</label>`).join('')}</div><div ${draft.mode==='dates'?'':'hidden'}><div class="ds-flex" style="margin-top:14px"><input type="date" id="ds-date" value="${draft.from}" style="flex:1"><button type="button" class="ds-secondary" data-do="adddate">+ ${t('Ajouter la date','Add date')}</button></div><div class="ds-options">${draft.dates.map((s,i)=>`<button type="button" class="ds-secondary" data-do="removedate" data-index="${i}" aria-label="${t('Retirer','Remove')} ${s}">${s} ×</button>`).join('')}</div></div><p>${t('Les dates passées sont exclues automatiquement. Maximum : un an par période.','Past dates are automatically excluded. Maximum: one year per range.')}</p></div><div class="ds-section"><div class="ds-flex"><h3>${t('Créneaux dans chaque journée','Time slots on each day')}</h3><button type="button" class="ds-secondary" data-do="addslot">+ ${t('Ajouter un créneau','Add a time slot')}</button></div>${draft.slots.map((s,i)=>`<div class="ds-slot"><label>${t('Début','Start')} ${i+1}<input type="time" name="start" value="${s.start}"></label><label>${t('Fin · même jour','End · same day')} ${i+1}<input type="time" name="end" value="${s.end}"></label><button type="button" class="ds-secondary" data-do="removeslot" data-index="${i}" ${draft.slots.length===1?'disabled':''}>${t('Retirer','Remove')}</button></div>`).join('')}${cfg.employee?`<p class="ds-notice">${t('Ces disponibilités ne vous obligent pas à accepter une offre. Vous pourrez fermer chaque créneau ou toute la série.','Availability does not commit you to accepting an offer. You can close individual slots or the entire series.')}</p>`:`<div class="ds-grid"><label>${t('Personnes nécessaires par quart','People needed per shift')}<input type="number" name="count" min="1" max="100" step="1" value="${draft.count}"></label>${cfg.scopes?`<label>${t('Diffusion','Visibility')}<select name="scope"><option value="network" ${draft.scope==='network'?'selected':''}>${t('Portail + Dispo','Portal + Dispo')}</option><option value="portal" ${draft.scope==='portal'?'selected':''}>${t('Portail seulement','Portal only')}</option></select></label>`:''}</div><label class="ds-check" style="margin-top:14px"><input name="sameTeam" type="checkbox" ${draft.sameTeam?'checked':''}>${t('Souhaiter retrouver les mêmes employés sur cette série','Prefer the same workers across this series')}</label><p>${t('Préférence uniquement : chaque quart doit être accepté. Aucune affectation automatique ni garantie de personnel.','A preference only: each shift must be accepted. No automatic assignment or staffing guarantee.')}</p>`}</div><div class="ds-preview" id="ds-preview" aria-live="polite"></div><div class="ds-grid"><label>${t('Nom du modèle (pour réutiliser ce poste)','Template name (to reuse this setup)')}<input id="ds-name" maxlength="60" placeholder="${t('Ex. Renfort fin de semaine','E.g. Weekend support')}"></label><div style="align-self:end"><button type="button" class="ds-secondary" data-do="save">${t('Enregistrer le modèle','Save template')}</button></div></div><p>${t('Enregistrer un modèle ne publie rien. Les dates restent à vérifier au prochain chargement.','Saving a template does not publish anything. Review the dates next time you load it.')}</p><div id="ds-error" class="ds-error" role="status"></div><div class="ds-actions"><button type="button" class="ds-secondary" data-do="close">${t('Annuler','Cancel')}</button><button type="button" id="ds-publish" data-do="publish">${t(cfg.employee?'Publier mes disponibilités simulées':'Publier les quarts simulés',cfg.employee?'Publish simulated availability':'Publish simulated shifts')}</button></div></section>`;preview()}
function close(){root?.remove();root=null;document.body.style.overflow=oldFocus.overflow;oldFocus.el?.focus()}
function open(options){if(root)close();cfg=options;let today=iso(new Date());draft={roleKey:String(cfg.roles[0].key),rate:24,count:1,branches:[cfg.branches[0]],mode:'single',from:today,to:today,days:[1,2,3,4,5],dates:[today],slots:[{start:'12:00',end:'16:00'}],scope:'network',sameTeam:false,...cfg.prefill};oldFocus={el:document.activeElement,overflow:document.body.style.overflow};root=document.createElement('div');root.className='ds-overlay';document.body.appendChild(root);document.body.style.overflow='hidden';draw();q('[data-do=close]').focus();root.addEventListener('change',e=>{collect();if(e.target.name==='mode'||e.target.name==='roleKey'||e.target.name==='individualTimes'||(cfg.employee&&draft.individualTimes&&['from','to','weekday'].includes(e.target.name)))draw();else preview()});root.addEventListener('input',e=>{if(e.target.id!=='ds-name')preview()});root.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const a=[...root.querySelectorAll('button,input,select,summary')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}});root.addEventListener('click',handle)}
function handle(e){let b=e.target.closest('[data-do]');if(!b)return;let a=b.dataset.do;collect();if(a==='close')return close();if(a==='otherdate'){q('#ds-other-date').hidden=false;b.setAttribute('aria-expanded','true');const input=q('#ds-date');input.focus();try{input.showPicker()}catch{}return}if(a==='addDateSlot'||a==='removeDateSlot'){let date=b.dataset.date;draft.dateSlots=draft.dateSlots||{};let slots=draft.dateSlots[date]||(draft.dateSlots[date]=structuredClone(draft.slots));if(a==='addDateSlot'&&slots.length<8)slots.push({start:'17:00',end:'21:00'});if(a==='removeDateSlot'&&slots.length>1)slots.splice(+b.dataset.index,1);draw();return}if(a==='quickdate'){let date=b.dataset.date;if(draft.mode!=='dates'){draft.mode='dates';draft.dates=[]}draft.dates=draft.dates.includes(date)?draft.dates.filter(d=>d!==date):[...draft.dates,date].sort();draw();return}if(a==='addslot'){if(draft.slots.length>=8)return;draft.slots.push({start:'17:00',end:'21:00'});draw()}if(a==='removeslot'){draft.slots.splice(+b.dataset.index,1);draw()}if(a==='allbranches'){draft.branches=[...cfg.branches];draw()}if(a==='month'){let m=q('#ds-month').value;if(!/^\d{4}-\d{2}$/.test(m))return;let [y,n]=m.split('-').map(Number);draft.from=m+'-01';draft.to=iso(new Date(y,n,0,12));draft.mode='daily';draw()}if(a==='adddate'){let val=q('#ds-date').value;try{parse(val);if(val<iso(new Date()))return;if(cfg.employee)draft.mode='dates';draft.dates=[...new Set([...draft.dates,val])].sort();draw()}catch{}}if(a==='removedate'){draft.dates.splice(+b.dataset.index,1);draw()}if(a==='save'){let name=q('#ds-name').value.trim();if(!name){q('#ds-error').textContent=t('Donnez un nom au modèle.','Give the template a name.');return}if(!preview(true))return;let ts=templates(),existing=ts.find(x=>x.name===name),item={id:existing?.id||(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),name,draft:structuredClone(draft)};ts=ts.filter(x=>x.id!==item.id);ts.unshift(item);try{localStorage.setItem(key(),JSON.stringify(ts.slice(0,30)));draw();q(cfg.employee?'#ds-save-status':'#ds-error').textContent=cfg.employee?t('Disponibilités enregistrées.','Availability saved.'):t('Modèle enregistré dans ce navigateur.','Template saved in this browser.')}catch{q('#ds-error').textContent=t('Le navigateur refuse l’enregistrement local.','This browser blocked local storage.')}}if(a==='load'){let item=templates().find(x=>x.id===q('#ds-template').value);if(!item)return;draft={...draft,individualTimes:false,dateSlots:{},...structuredClone(item.draft)};draft.branches=draft.branches.filter(x=>cfg.branches.includes(x));if(!cfg.roles.some(x=>String(x.key)===draft.roleKey))draft.roleKey=String(cfg.roles[0].key);draw();q('#ds-name').value=item.name}if(a==='delete'){let id=q('#ds-template').value;if(!id)return;try{localStorage.setItem(key(),JSON.stringify(templates().filter(x=>x.id!==id)));draw()}catch{q('#ds-error').textContent=t('Suppression locale impossible.','Local deletion failed.')}}if(a==='publish'){let rows=preview();if(!rows)return;let cb=cfg.onPublish,meta=structuredClone(draft);close();cb(rows,meta)}}
window.DispoPlanner={open,expand};
})();
